<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php'; require_login();
require_once __DIR__.'/../config/database.php';
$dni=trim($_GET['dni']??'');$estudiante=null;$recibos=[];$total=0.0;$error='';
if($dni!==''){
 if(!preg_match('/^\d{8}$/',$dni)) $error='Ingresa un DNI válido de 8 dígitos.';
 else{
  $q=$pdo->prepare('SELECT id,dni,nombres,direccion,programa_estudio FROM estudiantes WHERE dni=?');$q->execute([$dni]);$estudiante=$q->fetch();
  if($estudiante){$q=$pdo->prepare("SELECT r.id,r.numero,r.descripcion,r.total,r.medio_pago,r.fecha_emision,m.estado FROM recibos r JOIN movimientos m ON m.id=r.movimiento_id WHERE r.estudiante_id=? ORDER BY r.fecha_emision DESC,r.id DESC");$q->execute([$estudiante['id']]);$recibos=$q->fetchAll();foreach($recibos as $r)if($r['estado']==='CONFIRMADO')$total+=(float)$r['total'];}
 }
}
?>
